const trig = $('Execute Workflow Trigger').first().json;
const rateRes = $('Fetch Live Exchange Rates').first().json;
const rows = $('Fetch Subscriptions For Snapshot').all()
  .map(i => i.json)
  .filter(p => p && p.properties);

const today = $now.toFormat('yyyy-LL-dd');
const txt = (a) => (a || []).map(t => t.plain_text).join('');
const sel = (p) => (p && p.select ? p.select.name : null);
const symbol = { EUR: '€', USD: '$', GBP: '£', CHF: 'CHF ' };
const perYear = { 'Monthly': 12, 'Quarterly': 4, 'Every 6 months': 2, 'Yearly': 1 };
const divisor = { 'Monthly': 1, 'Quarterly': 3, 'Every 6 months': 6, 'Yearly': 12 };
const cycleWord = { 'Monthly': 'monthly', 'Quarterly': 'quarterly', 'Every 6 months': 'every 6 months', 'Yearly': 'yearly' };
const money = (cur, n) => (symbol[cur] ?? (cur + ' ')) + n.toFixed(2);
const cut = (t, n) => (t.length > n ? t.slice(0, n) + '…' : t);
const trialFlag = (s) => (s.status === 'Trial'
  ? ' | TRIAL: counted at the amount in the table; the price changes when the trial ends on ' + (s.anchor ?? '?') + '; notes: ' + cut(s.notes || '-', 200)
  : '');

// Exchange rates: 1 USD = r.EUR EUR, r.GBP GBP, r.CHF CHF (ECB via Frankfurter)
const r = rateRes && rateRes.rates ? rateRes.rates : null;
const okRates = r && [r.EUR, r.GBP, r.CHF].every(v => typeof v === 'number' && v > 0);
const rateDate = okRates ? rateRes.date : null;
const eurPer = okRates ? { EUR: 1, USD: r.EUR, GBP: r.EUR / r.GBP, CHF: r.EUR / r.CHF } : { EUR: 1 };

// Parse rows
const subs = rows.map(pg => {
  const p = pg.properties;
  const f = p['Renewal'] && p['Renewal'].formula ? p['Renewal'].formula : null;
  return {
    id: pg.id,
    name: txt(p['Name'] && p['Name'].title),
    status: sel(p['Status']),
    amount: p['Amount'] ? p['Amount'].number : null,
    currency: sel(p['Currency']),
    cycle: sel(p['Billing Cycle']),
    renewalType: sel(p['Renewal Type']),
    renewal: f ? (f.string ?? (f.date ? f.date.start : null)) : null,
    nextRenewal: p['Next Renewal'] && p['Next Renewal'].formula && p['Next Renewal'].formula.date ? p['Next Renewal'].formula.date.start : null,
    days: p['Days Until Renewal'] && p['Days Until Renewal'].formula ? p['Days Until Renewal'].formula.number : null,
    payment: sel(p['Payment Method']),
    use: sel(p['Use']),
    account: txt(p['Account'] && p['Account'].rich_text),
    autoRenew: p['Auto-Renew'] ? p['Auto-Renew'].checkbox : null,
    notes: txt(p['Notes'] && p['Notes'].rich_text),
    anchor: p['Renewal Anchor'] && p['Renewal Anchor'].date ? p['Renewal Anchor'].date.start : null,
  };
});

// 1) Table snapshot
const tableLines = subs.map(s =>
  '- id ' + s.id + ' | ' + s.name + ' | ' + (s.status ?? '?') + ' | ' +
  (s.amount ?? '?') + ' ' + (s.currency ?? '') + ' ' + (s.cycle ?? '?') + ' | renewal: ' + (s.renewal ?? '?') +
  (s.days != null ? ' (in ' + s.days + ' days)' : '') + ' | type ' + (s.renewalType ?? '?') +
  ' | paid with ' + (s.payment ?? '?') + ' | use ' + (s.use ?? '?') +
  ' | account ' + (s.account || '-') + ' | auto-renew ' + s.autoRenew +
  ' | notes: ' + (s.notes || '-')
);

// 2) Spending figures
const included = [];
const excluded = [];
for (const s of subs) {
  if (s.status !== 'Active' && s.status !== 'Trial') continue;
  let why = null;
  if (s.currency === 'Crypto') why = 'paid in crypto, no reliable EUR rate';
  else if (s.renewalType === 'Included in a plan') why = 'included in another plan';
  else if (s.cycle === 'Usage-based') why = 'usage-based, no fixed amount';
  else if (s.cycle === 'One-time') why = 'one-time payment';
  else if (s.amount == null || s.amount === 0) why = 'no amount';
  else if (!perYear[s.cycle]) why = 'no billing cycle';
  else if (!s.currency || !symbol[s.currency]) why = 'no supported currency';
  if (why) { excluded.push({ s, why }); continue; }
  included.push({
    s,
    monthly: s.amount / divisor[s.cycle],
    yearly: s.amount * perYear[s.cycle],
  });
}

const foreign = [...new Set(included.map(x => x.s.currency).filter(c => c !== 'EUR'))];
const convertible = foreign.every(c => eurPer[c] !== undefined);

let spending = [];
if (convertible) {
  for (const x of included) {
    x.mEur = x.monthly * eurPer[x.s.currency];
    x.yEur = x.yearly * eurPer[x.s.currency];
  }
  included.sort((a, b) => b.mEur - a.mEur);
  const totM = included.reduce((t, x) => t + x.mEur, 0);
  const totY = included.reduce((t, x) => t + x.yEur, 0);
  spending.push('Currency: EUR (converted with the live rates below). Included subscriptions (Active and Trial with an amount and a cycle), most to least expensive:');
  for (const x of included) {
    const conv = x.s.currency !== 'EUR';
    spending.push('- ' + x.s.name + ' | monthly €' + x.mEur.toFixed(2) + ' | yearly €' + x.yEur.toFixed(2) +
      (conv ? ' | original ' + money(x.s.currency, x.s.amount) + ' billed ' + cycleWord[x.s.cycle] : '') + trialFlag(x.s));
  }
  spending.push('TOTAL (exact, rounded only here): monthly €' + totM.toFixed(2) + ' | yearly €' + totY.toFixed(2) +
    ' (computed from unrounded values, so it can differ by a cent from the sum of the lines)');
  spending.push('Subscriptions counted: ' + included.length);
  if (foreign.length) {
    spending.push('RATE LINE to end the answer with: ' + foreign.map(c => c + ' converted at ' + eurPer[c].toFixed(4) + ' EUR').join(', ') + ' (ECB, ' + rateDate + ')');
  }
  if (okRates) {
    spending.push('OTHER CURRENCIES (use only if I explicitly ask for one; exact, same rates, same order):');
    for (const tgt of ['USD', 'GBP', 'CHF']) {
      let tm = 0;
      let ty = 0;
      spending.push(tgt + ':');
      for (const x of included) {
        const same = x.s.currency === tgt;
        const m = same ? x.monthly : x.mEur / eurPer[tgt];
        const y = same ? x.yearly : x.yEur / eurPer[tgt];
        tm += m;
        ty += y;
        spending.push('- ' + x.s.name + ' | monthly ' + money(tgt, m) + ' | yearly ' + money(tgt, y) +
          (same ? '' : ' | original ' + money(x.s.currency, x.s.amount) + ' billed ' + cycleWord[x.s.cycle]) +
          (x.s.status === 'Trial' ? ' | TRIAL (see above)' : ''));
      }
      const src = [...new Set(included.map(x => x.s.currency))].filter(c => c !== tgt);
      spending.push('TOTAL ' + tgt + ' (exact): monthly ' + money(tgt, tm) + ' | yearly ' + money(tgt, ty));
      if (src.length) {
        spending.push('RATE LINE for ' + tgt + ': ' + src.map(c => c + ' converted at ' + (eurPer[c] / eurPer[tgt]).toFixed(4) + ' ' + tgt).join(', ') + ' (ECB, ' + rateDate + ')');
      }
    }
  }
} else {
  const byCur = {};
  for (const x of included) {
    byCur[x.s.currency] = byCur[x.s.currency] || { m: 0, y: 0 };
    byCur[x.s.currency].m += x.monthly;
    byCur[x.s.currency].y += x.yearly;
  }
  spending.push('EXCHANGE RATES UNAVAILABLE right now (the lookup failed). Do NOT convert or guess any rate. Tell me the rate lookup failed and show every amount in its ORIGINAL currency, with one total per currency:');
  for (const x of included) {
    spending.push('- ' + x.s.name + ' | monthly ' + money(x.s.currency, x.monthly) + ' | yearly ' + money(x.s.currency, x.yearly) + trialFlag(x.s));
  }
  for (const c of Object.keys(byCur)) {
    spending.push('TOTAL ' + c + ': monthly ' + money(c, byCur[c].m) + ' | yearly ' + money(c, byCur[c].y));
  }
}
spending.push('NOT INCLUDED in totals (' + excluded.length + '):');
for (const e of excluded) {
  spending.push('- ' + e.s.name + ' | ' + e.why + ' | ' + (e.s.amount ?? '?') + ' ' + (e.s.currency ?? '') + ' ' + (e.s.cycle ?? '') + ' | notes: ' + cut(e.s.notes || '-', 120));
}

// 3) Live rates for conversions requested by the user (e.g. "in dollars")
let rates;
if (okRates) {
  rates = 'LIVE RATES (ECB via Frankfurter, ' + rateDate + '): 1 USD = ' + r.EUR + ' EUR; 1 GBP = ' + eurPer.GBP.toFixed(6) + ' EUR; 1 CHF = ' + eurPer.CHF.toFixed(6) + ' EUR. ' +
    'To convert an EUR amount: x' + (1 / eurPer.USD).toFixed(6) + ' = USD, x' + (1 / eurPer.GBP).toFixed(6) + ' = GBP, x' + (1 / eurPer.CHF).toFixed(6) + ' = CHF.';
} else {
  rates = 'LIVE RATES: unavailable (lookup failed).';
}

// The shared long-term memory from Notion, read on every message: how he wants to be treated and facts about him
const sharedMem = (() => { try { const j = $('Fetch Shared Memory').first().json; return typeof j.markdown === 'string' ? j.markdown.split('\n').filter((l) => !l.startsWith('>')).join('\n').trim() : null; } catch (e) { return null; } })();
const memory = 'WHAT YOU KNOW ABOUT ALEX (the shared Notion memory, read just now: apply every line)\n' + (sharedMem === null ? '(could not be read right now)' : sharedMem);
const snapshot = memory + '\n\n' + 'Read from Notion just now (' + today + '), ' + subs.length + ' rows.\n\n' +
  'TABLE:\n' + (tableLines.join('\n') || '(the table is empty)') + '\n\n' +
  'SPENDING FIGURES (exact, already calculated):\n' + spending.join('\n') + '\n\n' + rates;

return [{ json: { chat_id: trig.chat_id, agent_name: trig.agent_name, chatInput: trig.chatInput, snapshot } }];

// Notion writes this turn REALLY made, read from the agent's own tool calls and Notion's answers (never from the reply text).
// A write whose answer carries no saved id is left out: nothing was saved.
// Each line names the row (title from this run's reads or from the write itself) and the fields written, so memory alone shows what changed.
const SOURCES = ["Fetch Subscriptions For Snapshot"];
const out = $input.first().json;
const trig = $('Execute Workflow Trigger').first().json;
const WRITE = /create|update|add|confirm|mark|delete|trash|archive|log weekly/i;
const ID = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/g;
const TITLE_KEYS = ['Task Name', 'Subtask Name', 'Description', 'Name', 'Review', 'Title'];
const names = {};
const titleOf = (o) => {
  if (typeof o.name === 'string' && o.name) return o.name;
  if (typeof o.summary === 'string' && o.summary) return o.summary;
  for (const [k, v] of Object.entries(o.properties || {})) {
    if (v && v.type === 'title') return (v.title || []).map(t => t.plain_text).join('');
    if (TITLE_KEYS.includes(k) && typeof v === 'string') return v;
  }
  return null;
};
const collect = (x, depth = 0) => {
  if (depth > 8) return;
  if (typeof x === 'string') { if (!/^\s*[\[{]/.test(x)) return; try { x = JSON.parse(x); } catch (e) { return; } }
  if (Array.isArray(x)) { x.forEach(v => collect(v, depth + 1)); return; }
  if (!x || typeof x !== 'object') return;
  if (typeof x.id === 'string' && !names[x.id]) { const t = titleOf(x); if (t) names[x.id] = t; }
  for (const v of Object.values(x)) if (v && (typeof v === 'object' || typeof v === 'string')) collect(v, depth + 1);
};
for (const n of SOURCES) { try { collect($(n).all().map(i => i.json)); } catch (e) { /* that read did not run */ } }
const steps = out.intermediateSteps || [];
for (const s of steps) collect(s.observation);
const short = (v) => (typeof v === 'string' ? v : JSON.stringify(v)).replace(/\s+/g, ' ').slice(0, 150);
const lines = [];
for (const step of steps) {
  const tool = String((step.action && step.action.tool) || '');
  if (!WRITE.test(tool)) continue;
  const obs = typeof step.observation === 'string' ? step.observation : JSON.stringify(step.observation ?? '');
  // An error answer saved nothing, even though it carries ids (request_id, integration_id, the data_source id)
  if (/APIResponseError|"error"\s*:|object_not_found|validation_error|Could not find|MCP error|timed out/i.test(obs)) continue;
  const ids = [...new Set(obs.match(ID) || [])];
  if (!ids.length || /"properties":\{\}/.test(obs)) continue;
  const inp = (step.action && step.action.toolInput) ?? {};
  const label = (id) => (names[id] ? '"' + names[id] + '" (' + id + ')' : id);
  // ids already in the input are the row being updated or rows the new one links to; the others are the rows just created
  const inInput = JSON.stringify(inp);
  const isCreate = /create|add/i.test(tool);
  const saved = isCreate ? ids.filter(id => !inInput.includes(id)) : ids;
  const linked = isCreate ? ids.filter(id => inInput.includes(id)) : [];
  const fields = (p) => Object.entries(p).map(([k, v]) => k + ' = ' + short(v)).join('; ');
  const props = inp && typeof inp === 'object' && inp.properties && typeof inp.properties === 'object' && !Array.isArray(inp.properties) ? inp.properties : null;
  const pages = inp && typeof inp === 'object' && Array.isArray(inp.pages) ? inp.pages : null;
  const written = props ? fields(props) : pages ? pages.map(p => fields(p.properties || {})).join(' || ') : JSON.stringify(inp).replace(/\s+/g, ' ').slice(0, 700);
  lines.push('- ' + tool + ' -> saved in Notion: ' + (saved.length ? saved : ids).map(label).join(', ') + (linked.length ? ' | linked to: ' + linked.map(label).join(', ') : '') + ' | written: ' + written);
}
const action_log = lines.length
  ? '[ACTION LOG, ' + $now.toFormat('yyyy-LL-dd HH:mm') + ', written by the workflow from the tool results of my previous reply: these Notion writes are DONE. Never make them again.]\n' + lines.join('\n')
  : '';
const { intermediateSteps, ...reply } = out;
// The agent sometimes copies an earlier action log from its chat memory into its reply: never send it
if (typeof reply.output === 'string') reply.output = reply.output.replace(/\s*\[ACTION LOG[^\]\n]*\][^\n]*(\n- [^\n]*)*/g, '').trim();
return [{ json: { ...reply, chat_id: String(trig.chat_id ?? ''), agent_name: trig.agent_name || 'subscriptions', action_log } }];

// What this turn adds to the agent's chat memory (Postgres), saved by Save To Memory:
// the ACTION LOG, i.e. the Notion writes this turn really made (from Build Action Log), as a hidden message,
// stored exactly as the Chat Memory Manager stored it. Nothing to save gives an empty list.
const log = $('Build Action Log').first().json;
const session_id = 'demo-' + log.chat_id + '-' + log.agent_name;
const ai = (content, hidden) => ({ type: 'ai', content, tool_calls: [], additional_kwargs: hidden ? { hideFromUI: true } : {}, response_metadata: {}, invalid_tool_calls: [] });
const writes = log.action_log ? [{ op: 'add', session_id, message: ai(String(log.action_log), true) }] : [];
return [{ json: { writes } }];
